from html.parser import HTMLParser
VOID={'area','base','br','col','embed','hr','img','input','link','meta','source','track','wbr'}
class P(HTMLParser):
    def __init__(s):
        super().__init__(convert_charrefs=True); s.stack=[]; s.hits=[]
    def handle_starttag(s,t,a):
        d=dict(a); cls=d.get('class','')
        if t not in VOID: s.stack.append((t,cls))
        if 'text-[#24ae1d]' in cls:
            s.hits.append(list(s.stack))
    def handle_endtag(s,t):
        for i in range(len(s.stack)-1,-1,-1):
            if s.stack[i][0]==t: del s.stack[i:]; break
p=P(); p.feed(open('enable.html',encoding='utf-8',errors='replace').read())
